var e = p.ecc;
var pad = 46;
var s = Math.min((W - pad * 2) / 2.35, (H - 44) / 2.05);
var cx = W / 2 + s * e * 0.5;
var cy = H / 2;
var b = Math.sqrt(1 - e * e);
var X = function (x) { return cx + x * s; };
var Y = function (y) { return cy - y * s; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.6;

// the ellipse (focus at origin of x,y)
ctx.strokeStyle = C.figure;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var E = i * Math.PI * 2 / 200;
  var x = Math.cos(E) - e, y = b * Math.sin(E);
  i === 0 ? ctx.moveTo(X(x), Y(y)) : ctx.lineTo(X(x), Y(y));
}
ctx.closePath();
ctx.stroke();

// major axis from aphelion to perihelion
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(-1 - e), Y(0)); ctx.lineTo(X(1 - e), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(X(-e), Y(-b)); ctx.lineTo(X(-e), Y(b)); ctx.stroke();
ctx.setLineDash([]);

// centre, empty focus, Sun at the occupied focus
ctx.fillStyle = C.rule;
ctx.beginPath(); ctx.arc(X(-e), Y(0), 3, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(-2 * e), Y(0), 3, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(0), Y(0), 6, 0, Math.PI * 2); ctx.fill();

// the c = ae offset
ctx.strokeStyle = C.accent;
ctx.beginPath(); ctx.moveTo(X(-e), Y(0)); ctx.lineTo(X(0), Y(0)); ctx.stroke();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("Sun (focus)", X(0), Y(0) + 20);
ctx.fillText("centre", X(-e), Y(0) - 10);
ctx.fillText("empty focus", X(-2 * e), Y(0) + 20);
ctx.fillText("c = ae", X(-e / 2), Y(0) - 26);
ctx.textAlign = "left";
ctx.fillText("perihelion  a(1-e)", X(1 - e) - 96, Y(0) - 12);
ctx.fillText("aphelion  a(1+e)", X(-1 - e) + 4, Y(0) - 12);
ctx.fillText("b = a sqrt(1-e^2)", X(-e) + 6, Y(b * 0.55));
ctx.fillStyle = C.figure;
ctx.fillText("semi-major axis a", X(-e) + 6, Y(0) + 16);

out.note = "e = " + e.toFixed(2) + "   perihelion = " + (1 - e).toFixed(3) + " a   aphelion = " + (1 + e).toFixed(3) + " a   b = " + b.toFixed(3) + " a";

var e = p.ecc;
var period = 8.0;
var frac = p.sweep / 100;
var b = Math.sqrt(1 - e * e);
var pad = 34;
var s = Math.min((W - pad * 2) / 2.3, (H - 52) / 2.05);
var cx = W / 2 + s * e * 0.5;
var cy = H / 2 + 6;
var X = function (x) { return cx + x * s; };
var Y = function (y) { return cy - y * s; };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// solve Kepler's equation M = E - e sin E by Newton iteration
var posAt = function (time) {
  var M = 2 * Math.PI * (time / period);
  M = M - Math.floor(M / (2 * Math.PI)) * 2 * Math.PI;
  var E = M;
  for (var k = 0; k < 24; k++) {
    E = E - (E - e * Math.sin(E) - M) / (1 - e * Math.cos(E));
  }
  return [Math.cos(E) - e, b * Math.sin(E)];
};

// orbit outline
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.4;
ctx.beginPath();
for (var i = 0; i <= 220; i++) {
  var E2 = i * Math.PI * 2 / 220;
  var ox = Math.cos(E2) - e, oy = b * Math.sin(E2);
  i === 0 ? ctx.moveTo(X(ox), Y(oy)) : ctx.lineTo(X(ox), Y(oy));
}
ctx.closePath();
ctx.stroke();

// two swept wedges of equal duration: one at perihelion, one at aphelion
var dt = frac * period;
var wedge = function (t0) {
  ctx.beginPath();
  ctx.moveTo(X(0), Y(0));
  for (var j = 0; j <= 40; j++) {
    var q = posAt(t0 + dt * j / 40);
    ctx.lineTo(X(q[0]), Y(q[1]));
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
};
ctx.fillStyle = C.faint;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1;
wedge(-dt / 2);
wedge(period / 2 - dt / 2);

// moving planet and its radius line
var now = t % period;
var q0 = posAt(now);
var r = Math.sqrt(q0[0] * q0[0] + q0[1] * q0[1]);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(X(0), Y(0)); ctx.lineTo(X(q0[0]), Y(q0[1])); ctx.stroke();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(q0[0]), Y(q0[1]), 5, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(X(0), Y(0), 6, 0, Math.PI * 2); ctx.fill();

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("Sun", X(0), Y(0) + 20);
ctx.fillText("fast, short wedge", X(1 - e), Y(0) - 16);
ctx.fillText("slow, long wedge", X(-1 - e) + 40, Y(0) - 16);
ctx.textAlign = "left";

// both wedges have the same area: report it
var area = Math.PI * b * frac;
var v = Math.sqrt(2 / r - 1);
out.note = "each wedge spans " + (frac * 100).toFixed(0) + "% of the period, area = " + area.toFixed(3) + " a^2 each   |   planet now at r = " + r.toFixed(3) + " a, speed = " + v.toFixed(2) + " (units of sqrt(GM/a))";

var aMax = 32;
var tMax = Math.pow(aMax, 1.5);
var padL = 46, padB = 34, padT = 16, padR = 14;
var X = function (a) { return padL + (a / aMax) * (W - padL - padR); };
var Y = function (T) { return H - padB - (T / tMax) * (H - padB - padT); };
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.2;

// axes
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(padL, padT); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("T (years)", padL - 40, padT + 10);
ctx.fillText("a (AU)", W - padR - 44, H - padB + 22);
var gx, gy;
for (gx = 10; gx <= 30; gx += 10) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(gx), H - padB); ctx.lineTo(X(gx), padT); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(String(gx), X(gx) - 6, H - padB + 16);
}
for (gy = 50; gy <= 150; gy += 50) {
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(padL, Y(gy)); ctx.lineTo(W - padR, Y(gy)); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.fillText(String(gy), padL - 28, Y(gy) + 4);
}

// the curve T = a^(3/2)
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.8;
ctx.beginPath();
for (var i = 0; i <= 200; i++) {
  var a = aMax * i / 200;
  i === 0 ? ctx.moveTo(X(a), Y(Math.pow(a, 1.5))) : ctx.lineTo(X(a), Y(Math.pow(a, 1.5)));
}
ctx.stroke();

// real bodies sit on the curve
var names = ["Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"];
var axes = [1.0, 1.524, 5.203, 9.537, 19.19, 30.07];
ctx.fillStyle = C.rule;
for (var k = 0; k < axes.length; k++) {
  var Tk = Math.pow(axes[k], 1.5);
  ctx.beginPath(); ctx.arc(X(axes[k]), Y(Tk), 3.5, 0, Math.PI * 2); ctx.fill();
  ctx.fillText(names[k], X(axes[k]) + 6, Y(Tk) + 2);
}

// the reader's body
var aSel = p.a;
var tSel = Math.pow(aSel, 1.5);
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(aSel), H - padB); ctx.lineTo(X(aSel), Y(tSel)); ctx.lineTo(padL, Y(tSel)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(aSel), Y(tSel), 5, 0, Math.PI * 2); ctx.fill();

out.note = "a = " + aSel.toFixed(2) + " AU  ->  T = a^1.5 = " + tSel.toFixed(2) + " years   (T^2/a^3 = " + (tSel * tSel / (aSel * aSel * aSel)).toFixed(3) + ", the same for every body here)";
